import{_ as t,o as l,c as e,a2 as s}from"./chunks/framework.Cs11k9ph.js";const p=JSON.parse('{"title":"🧩 连接插件端（ClassIsland 一体机）","description":"","frontmatter":{},"headers":[],"relativePath":"plugin.md","filePath":"plugin.md","lastUpdated":1788113045000}'),o={name:"plugin.md"};function d(i,a,r,n,c,h){return l(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="🧩-连接插件端-classisland-一体机" tabindex="-1">🧩 连接插件端（ClassIsland 一体机） <a class="header-anchor" href="#🧩-连接插件端-classisland-一体机" aria-label="Permalink to &quot;🧩 连接插件端（ClassIsland 一体机）&quot;">​</a></h1><blockquote><p>本文档对应 <strong>AgoraIn v3.2</strong>。插件端即运行在 <strong>ClassIsland 2.x</strong>（教室一体机/电子白板）上的联动插件，用于接收教师端发送的呼叫并<strong>置顶弹窗 + 中文语音朗读</strong>。</p></blockquote><hr><h2 id="插件端是什么" tabindex="-1">插件端是什么 <a class="header-anchor" href="#插件端是什么" aria-label="Permalink to &quot;插件端是什么&quot;">​</a></h2><p><code>AgoraIn.ClassIslandPlugin</code>（2.1.1.0）运行在 ClassIsland 主程序进程内，定时向集控平台轮询本机待处理呼叫：</p><table tabindex="0"><thead><tr><th>呼叫类型</th><th>触发方式</th></tr></thead><tbody><tr><td>⏰ 待下课时段通知</td><td>结合 ClassIsland 课表，在「距下课 ≤ 提前分钟数」的窗口内自动弹出（蓝色）</td></tr><tr><td>🚨 上课应急通知</td><td>立即弹出（红色）并朗读</td></tr><tr><td>📢 下课传唤</td><td>立即弹出（橙色）并朗读，附传唤学生名单</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>测试呼叫<strong>请使用「上课应急通知」或「下课传唤」</strong>，两者立即弹窗；「待下课时段通知」只在临近下课窗口触发，是设计行为而非故障。</p></div><hr><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><ul><li>教室一体机：Windows 10/11，安装 <a href="https://classisland.tech" target="_blank" rel="noreferrer">ClassIsland 2.x</a></li><li>已部署并运行的 AgoraIn 集控服务器（<a href="/deploy.html">部署指南</a>）</li><li>教师端已连接该服务器（「控制模式 → 集控平台列表」）</li></ul><hr><h2 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h2><ol><li>在<a href="/download.html">下载中心</a> <strong>Windows</strong> 页签下载 <code>ClassIsland.Plugin.cipx</code>（约 353 KB）</li><li>打开 ClassIsland → <code>设置 → 插件管理 → 本地安装</code>，选择该 cipx 文件（已装旧版请先卸载）</li><li>重启 ClassIsland，确认顶部日志出现：<code>此次会话已加载插件:AgoraIn 联动插件(agorain.classisland,2.1.1.0)</code></li></ol><hr><h2 id="第二步-配置连接" tabindex="-1">第二步：配置连接 <a class="header-anchor" href="#第二步-配置连接" aria-label="Permalink to &quot;第二步：配置连接&quot;">​</a></h2><p>进入 ClassIsland → <code>设置 → 插件设置 → AgoraIn 联动</code>，填写三项（或点 <strong>自动探测</strong> 读取本机大屏客户端配置）：</p><table tabindex="0"><thead><tr><th>配置项</th><th>填写内容</th></tr></thead><tbody><tr><td>集控平台地址</td><td><code>http://服务器IP:5250</code>（如 <code>http://192.168.31.3:5250</code>）</td></tr><tr><td>连接密码</td><td>与服务器 <code>config.json</code> 的 <code>ServerPassword</code> 一致（默认 <code>admin123</code>）</td></tr><tr><td>设备 UUID</td><td><strong>必须</strong>填写教师端「控制模式 → 设备列表」中该一体机对应的 UUID</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>设备 UUID 是三项中最容易出错的一项。</strong> 教师端发送呼叫时按设备列表选择目标，只有 <strong>教师端发送目标 == 插件端设备 UUID</strong> 时才会收到呼叫。 UUID 即大屏客户端的 <code>client_uuid.txt</code> 内容；如果本机没有大屏客户端，请先在教师端设备列表确认该一体机记录再填写。</p></div><p>保存后插件自动重启轮询：<strong>3 秒后开始、此后每 10 秒一次</strong>（可在设置页调整 5–120 秒）。</p><hr><h2 id="第三步-验证连接" tabindex="-1">第三步：验证连接 <a class="header-anchor" href="#第三步-验证连接" aria-label="Permalink to &quot;第三步：验证连接&quot;">​</a></h2><ol><li>教师端「控制模式 → 设备列表」中选中该一体机 → <strong>发送到所选</strong> → 选「上课应急通知」并填写标题</li><li>等待约 15 秒，一体机应弹出置顶窗口并朗读：<code>上课应急通知，&lt;标题&gt;…</code></li><li>校验服务器数据库（可选）：该呼叫记录状态变为 <code>acknowledged</code> 说明插件已拉取并确认</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT Id, Title, Status FROM Calls ORDER BY Id DESC LIMIT 5;</span></span>
<span class="line"><span>-- Status = acknowledged 表示插件端已收到并显示</span></span></code></pre></div><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="收不到呼叫" tabindex="-1">收不到呼叫 <a class="header-anchor" href="#收不到呼叫" aria-label="Permalink to &quot;收不到呼叫&quot;">​</a></h3><ul><li><strong>UUID 不一致</strong>（最常见）：确认插件设置与教师端发送目标为同一台设备</li><li>插件未启动：确认日志出现 <code>已加载插件</code>；轮询依赖网络，一体机需能访问服务器 5250 端口</li><li>呼叫已过期：<code>calls_pull</code> 会把超过 2 小时的 pending 呼叫标记为过期</li></ul><h3 id="弹了但不朗读" tabindex="-1">弹了但不朗读 <a class="header-anchor" href="#弹了但不朗读" aria-label="Permalink to &quot;弹了但不朗读&quot;">​</a></h3><ul><li>新版 2.1.1.0 已内置朗读（System.Speech），请先升级插件</li><li>系统还原语音：Windows <code>设置 → 时间和语言 → 语音</code>，确认已安装中文语音（如 Microsoft Huihui）</li></ul><h3 id="待下课通知迟迟不弹" tabindex="-1">待下课通知迟迟不弹 <a class="header-anchor" href="#待下课通知迟迟不弹" aria-label="Permalink to &quot;待下课通知迟迟不弹&quot;">​</a></h3><ul><li>「待下课通知」只在距下课 ≤ 提前分钟数时触发；ClassIsland 当前无课表数据时视为立即触发</li><li>可临时改发「应急/传唤」验证链路</li></ul><h3 id="插件设置不生效" tabindex="-1">插件设置不生效 <a class="header-anchor" href="#插件设置不生效" aria-label="Permalink to &quot;插件设置不生效&quot;">​</a></h3><ul><li>每项修改后记得点 <strong>保存</strong>（会重启轮询）</li><li>配置文件位置：<code>ClassIsland数据目录\\Config\\Plugins\\agorain.classisland\\settings.json</code></li></ul><hr><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/download.html">下载中心</a> — 获取 <code>ClassIsland.Plugin.cipx</code></li><li><a href="/features.html">功能特性</a> — 完整功能说明</li><li><a href="/guide.html">快速开始</a> — 从零搭建全套环境</li><li><a href="/deploy.html">部署指南</a> — 集控服务器部署</li></ul>`,36)])])}const g=t(o,[["render",d]]);export{p as __pageData,g as default};
